      const idlName = propertyToIDL(property);
      const target = createTestElement(t, setup);
      target.style[idlName] = 'blur(10px)';
      const animation = target.animate({ [idlName]: ['brightness(80%)',
                                                     'brightness(40%)'] },
                                       { duration: 1000, composite: 'add' });
